INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('lepidosaur', 'Lepidosaur', 'animal', 'rifts', 0, 'Animal, considered Anarchist', '{"IQ":"1D4+5","ME":"1D6","MA":"1D6+3","PS":"1D4+2","PP":"1D4+22","PE":"1D6+12","PB":"1D6+6","Spd":"1D4+6"}', NULL, NULL, '1D4+4', '2D6+12', NULL, 'A very minor Mega-Damage creature. I.Q. is medium to high animal intelligence. Spd 1D4+6 is on the ground; 1D6+20 leaping and climbing through trees and 1D6+34 flying (an average of 6, 5 mph/8 km, walking and 36, 27 mph/43.2 km, flying). On S.D.C. worlds: 3D6 S.D.C., Hit Points equal to the P.E., A.R. 10.', NULL, NULL, '{"attacks":4,"perception":2,"initiative":2,"strike":3,"dodge":3,"roll":2}', '+2 on Perception Rolls, +2 on initiative, +3 to strike, +2 to disarm, +3 to dodge, +2 to roll with impact. All in addition to possible attribute bonuses. Horror Factor: none for one alone; 8 for a group of 6-12 and 14 for an unusually large flock of 24-32.', 'Track by sight 45%.', 'Excellent at climbing trees and leaping from branch to branch, a good flier, with color vision and keen hearing; it marks out the wounded, injured or sick. Latching Attack: a claw that hooks the victim (30% chance, or a strap or seam of clothing or armor) gives it one extra attack per melee round, +2 to strike with a bite that does an extra 1D4 S.D.C. Swarming Attack: when six or more concentrate on one victim, he sees only a flurry of wings and claws, is -7 to strike, parry and dodge and -25% on skills, and takes 4D6 S.D.C. per melee round (15 seconds) from glancing blows, on top of the one member that flies in for the serious bite or foot claw, the only one that may use the Latching Attack. Dodging the swarm is useless; the victim can parry, take cover under a shield or dive into a confined dark place most will not enter, or strike at the attacker coming in. Killing one or two of the flock drives them all off. The Quick Find lists it among the poisonous creatures (printed 47), but its entry prints no venom.', 'Each of these once per day at will without spending P.P.E., as a first level practitioner of magic; casting one again within 24 hours draws on its own P.P.E., never more than half its reserve: Change Wind Direction (6), Cloak of Darkness (4), Create Mild Wind (4) and Mesmerism (7).', 'None.', '1-1.5 feet (0.3 to 0.45 m) from the top of the head to the rump, plus a tail of 1-1.5 feet (0.3 to 0.45 m); wingspan 2-3 feet (0.6 to 0.9 m)', '3-5 pounds (1.35 to 2.25 kg)', '4-8 years', 'High in the trees throughout Dinosaur Swamp, most numerous in Georgia and the Carolinas, where they compete with the Azhures in the SteelTree Forest; spreading through the southeast and across the Appalachian Mountains', 'None per se, other than their own extended family', 'Snakes, Azhures and other birds of prey, rival Lepidosaur family groups, and humanoids', 'None; animal.', 'A raven-sized flying reptile of the Horror Forest, the South Carolina woods and the eastern Appalachians, with fan-like wings off its ribs, a prehensile whip tail, two-taloned feet, barbed little hand claws and a narrow beak holding three rows of tiny razor teeth. Alone it is a nuisance; a hungry family flock of 1D6+6 breaks up a party, cuts out the slow, sick or weak, and brings them down with Air Elemental-like magic. Value: 20 credits a carcass as food; wing and rib bones serve barbarians as needles and leather punches (1 credit per 3 bones). Mages take them as familiars, and Char sells them as pets and hunting falcons for 100-600 credits; many barbarian villages keep 2-6 to hunt rabbits, quail and ducks.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.47-48'),
('raptor-king', 'Raptor King', 'monster', 'rifts', 1, 'Anarchist (20%), Miscreant (50%), Diabolic (20%) or Aberrant (10%); a player character raised among humans may be Unprincipled, but never good', '{"IQ":"2D4+12","ME":"2D6+14","MA":"2D6+8","PS":"1D6+16","PP":"1D6+14","PE":"1D6+18","PB":"1D6+6","Spd":"1D6+43 min 44"}', NULL, NULL, '6D6+66', 'PEx2+1D6+4', 'MEx2+2D4', 'Mega-Damage by location: Head 100; Forearms (2) 3D6+22 each; Hind Legs (2) 4D6+50 each; Tail 3D6+30; Main Body 6D6+66. Human intelligence. Minimum speed 44 (30 mph/48 km). P.P.E. is the P.E. x2 plus 1D6+4 per level of experience (the stored formula is first level), and the Practitioner of Magic M.O.S. adds 1D20+6; I.S.P. is the M.E. x2 plus 2D4 per level. On S.D.C. worlds: 4D6+30 S.D.C., Hit Points equal to the P.E. x5, A.R. 11, and its attacks do S.D.C. instead of M.D.', NULL, 12, '{"attacks":5,"perception":4,"initiative":3,"strike":2,"parry":2,"dodge":2}', 'Five attacks per melee for males and six for females, +1 for both at levels 5, 9 and 13. +4 on Perception Rolls, +3 on initiative, +2 to strike and parry, +2 to dodge and disarm, +5 to save vs Horror Factor. All in addition to likely attribute bonuses. Horror Factor 12 alone, 14 with 2-6 Raptors and 16 with a pack of 7 or more.', 'O.C.C. skills as a sort of M.O.S., one package. Wilderness Scout: five Wilderness skills (+20% each), three Domestic, two Languages of choice (+10%), three Ancient W.P.s and two Modern (any except Heavy M.D. Weapons). Scholar/Explorer: three Wilderness (+10%), three Science (+10%), two Communications (+5%), three Languages of choice (+20%), two Technical or Medical (+10%), two Ancient W.P.s and one Modern. Practitioner of Magic: two Wilderness (+10%), four Lore (+20%), two Technical, two Languages of choice (+10%), one Ancient W.P. and one Modern, plus 1D20+6 P.P.E. Bandit/Raider: three Wilderness (+10%), four Rogue (+12%), two Espionage (+5%), two Languages of choice (+15%), two Ancient W.P.s and two Modern. Natural skills: track blood scent 75%, Track Animals and Humanoids by scent or vision 65%, Prowl 67%, Detect Ambush 70%, Climb 80%/60%, Wilderness Survival 90%.', 'Keen hearing, daytime vision as good as perfect human sight, nightvision 100 feet (30.5 m). Runs for 4 hours without pause or tiring; its leap reaches 10 feet (3 m) up and 15 feet (4.6 m) out, 30% more at full speed. Goes two weeks without food or water; eats only meat, blood and bone, live or carrion, rotten included, and smells blood a mile (1.6 km) off. Can learn one or more human languages and speak them in a human-sounding voice. Bio-regenerates 1D6 M.D.C. an hour, 4D6 an hour on a ley line and 1D6x10 an hour at a nexus, and regrows a lost tail, eye, finger or toe. Raptor Rapport: no Raptor of any kind (Tiger Claw Raptors, Velociraptors and the like), pack leaders included, will attack or harm it, nor can one be forced or mind controlled into doing so (only possession works); Raptors accept it as leader by instinct and will die or kill themselves on its command. Its semi-prehensile tail swings like a cat''s for a blunt 1D4 M.D. strike but cannot grip, carry or hang from anything. Vulnerable: cannot swim, dislikes deep water in rivers, lakes and the ocean, and underestimates humanoid opponents.', 'Starts with two Level One Invocations and one each from Levels Two and Three, gains two more at levels 2, 3, 4 and 5 and one per level after that, all from Invocation Levels 1-6; like the Mystic it simply knows each new spell. Uses Eco-Wizard, Techno-Wizard and other magic weapons and devices.', 'Major Psionic with an expanded range: starts with Telepathy (4), Object Read (6), See the Invisible (4) and Sixth Sense (2); one Physical or Sensitive power at levels 2, 4, 6, 8, 10, 12 and 14, and one Super-Psionic power at levels 3, 7 and 13. Raptor Control (special): a telepathic call, 1000 foot (305 m) radius per level, that finds and commands Raptors in range, up to one per level, held indefinitely; for a total of eight minutes per 24 hours it can command triple that number.', '6-6.5 feet (1.8 to 2 m) tall, plus a thick semi-prehensile tail about 4 feet (1.2 m) long', '180 to 250 pounds (81 to 112.5 kg)', 'Unknown; believed to be 80-130 years', 'Anywhere in Dinosaur Swamp, especially places of magic, ancient ruins and other places of interest; seldom leaves the southeast, though a few have journeyed to the Magic Zone, the New West, Mexico and Central and South America; avoids cold regions', 'Evil and selfish beings may ally with it or work for it, but it is true only to itself', 'All others are fools, pawns, slaves or food to it', 'An optional R.C.C. (so the Quick Find lists it) whose use by players the book leaves wholly to the Game Master, with four M.O.S. skill packages (skills_note). Imported as a creature row only, not a class, the way the Wraith Soldier was (Nate''s ruling D20, 2026-10-19). Experience as the Ley Line Walker; player characters start at level 1-2, and NPCs are any level or 1D6+2, most of them level 4-7.', 'Also called the Terrible Swamp Man: a stocky, thick-muzzled Raptor with heavier limbs, shorter claws and an opposable thumb, green to golden with a pale belly, whose human mind hides easily behind an animal act; the jewelry, feathers, skulls and slung weapons it wears are what give it away. A solitary wanderer of unknown origin that meets its own kind only to mate once every twelve years and rarely stays anywhere six months. It covets gems and every kind of magic item, above all Eco-Wizard work, Rune Weapons and Splugorth Bio-Wizardry, and is leery of Techno-Wizardry. At least half eat humans, who are to it knowledge to steal, worshipers, slaves or food; barbarian and Eco-Wizard tribes seek its counsel on war, treachery and magic and host it as a feared guest. About half keep 1-4 Raptors as companions, and the most violent lead whole packs of 6-16. Its Raptor Rapport and psionic command make every Raptor its servant. Deearn Neenok suspects it is a myth and hopes to catch one.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.49-51'),
('razorback-rhinoceros', 'Razorback Rhinoceros', 'animal', 'rifts', 0, 'An aggressive animal omnivore, considered Anarchist', '{"IQ":"1D4+6","ME":"1D6+10","MA":"2D6+10","PS":"2D6+30","PP":"1D6+20","PE":"1D6+20","PB":"1D6+16","Spd":"2D8+28 min 30"}', NULL, NULL, '1D6x100+240', '3D6', NULL, 'Mega-Damage by location: Head and Shield 1D4x100+400; Nose Horn (1, large) 200*; Head and Shield Spikes (many, at least 20) 15 each*; Spine Blades (many, at least 50 from neck to tail tip) 12 each*; Eye Stalks (2) 45 each*; Front Legs (2) 110 each; Hind Legs (2) 160 each; Main Body 1D6x100+240. * a Called Shot at -5 to strike. Supernatural P.S. and P.E. I.Q. is high animal intelligence. Minimum speed 30 (20 mph/32 km); it runs at twice its speed in bursts of 30 seconds for a crippling charge. On S.D.C. worlds: 1D6x100 S.D.C., 1D4x100 Hit Points, A.R. 16, and its attacks do S.D.C. instead of M.D.', NULL, 12, '{"attacks":4,"initiative":4,"perception":2,"strike":3,"parry":4,"dodge":2,"roll":3}', '+4 on initiative, +2 on Perception Rolls, +3 to strike and disarm, +4 to parry, +2 to dodge, +3 to roll with impact or fall, +3 to save vs disease and poison, +6 to save vs Horror Factor. All in addition to likely attribute bonuses.', 'Tracks the scent of blood or rotting meat up to half a mile (0.8 km) 78%; Swim 58%; Land Navigation 90%; Detect Ambush 80%; fakes being weak, sick, wounded or crippled 88% and dying 80%.', 'Good speed, though it holds top speed for only two hours; its reflexes are superb, and it enjoys a fight. Goes up to four weeks without food or water, though it eats every 2-3 days. Keen vision with polarized filters against glare and bright light, excellent hearing and a good nose; it follows buzzards and Leatherwings to carrion. Its eyes ride prehensile stalks that weave and duck under the jaw or behind the shield. Barks and growls like a dog and snorts when annoyed; tail swishing, pawing and kicking up dirt are warnings to back off. Spine Armored Defense: armor and sharp spikes cover its head, neck shield and spine, so anything leaping onto its back, neck or head takes 2D4 M.D., and a bigger predator biting or clawing it takes 2D6+2 M.D. The Pretender: it plays lame, sick or dying to lure predators in, then turns on them. Defensive by habit, it waits for the other side to strike; given a melee round or two of no action it gives its warnings and backs off, unless hungry, and once in a fight it goes on until one side is dead or flees.', 'None.', 'None.', '6 feet (1.8 m) tall at the shoulders and 18-22 feet (5.4 to 6.7 m) from snout to rump, plus a semi-prehensile tail of 20-25 feet (6.1 to 7.6 m)', '3-4 tons', '50 years', 'Woodlands, scrub plains and the lower reaches of the Appalachian Mountains; much less common in the marshlands, since it dislikes getting wet', 'None per se; wanders and hunts alone, in mated pairs or in groups of 3-6, and tolerates its own kind and Tri-Tops', 'Large predators and pack hunters', 'None; animal.', 'Not a placid grazer but a belligerent omnivore of meat, carrion, plants and garbage whose favorite prey is other predators: it grazes in the open or limps as if lame to bait Raptors, Allosaurus, T-Rex and Sarcosuchus, then rears or lunges to gore them first, its armored neck shield and spikes taking the counterblows. A gore or two to the belly or neck can gut a T-Rex in a melee round, after which it goes for a leg. Humans who freeze, back away slowly or kneel and play dead are usually let go. Value: 5000-7000 credits for a young one to train as a riding animal, ridden standing or in a protective saddle; a spike makes a 1D4 M.D. weapon (the bigger ones 1D6) or jewelry, and the hide makes light M.D.C. fabric (a poncho or overcoat 10 M.D.C., padded 15-20, a tent 18). The meat is tough and unsold, and most tribes revere it as a trickster spirit and seldom hunt it.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.52-54'),
('razormouth-frog', 'Razormouth Frog', 'animal', 'rifts', 0, 'Animal predator, considered Miscreant or Diabolic', '{"IQ":"1D4","ME":"2D6","MA":"1D6","PS":"4D6+10","PP":"2D6","PE":"2D6+20","PB":"1D6","Spd":"1D6+6 min 7"}', NULL, NULL, '1D4x10+5', '2D6', NULL, 'The attributes are for a frog big enough to threaten human-sized prey. M.D.C. 1D4x10+5 for one the size of an easy chair or couch (stored), 2D4x10+12 for one the size of an SUV or mini-van, 4D4x10+32 for giants larger than that. Supernatural P.S. and P.E. I.Q. is very low animal intelligence. Minimum speed 7 (5 mph/8 km), most 9 (7 mph/11.2 km) on dry land, triple that underwater. In S.D.C. environments: S.D.C. equal to those M.D.C. numbers, Hit Points equal to the P.E. x2, A.R. 8, and its bite does S.D.C. instead of M.D.', NULL, 14, '{"attacks":3,"strike":3}', '+3 to strike, in addition to possible attribute bonuses. It cannot dodge. Horror Factor 14-18 by its size and by whether the victim has M.D.C. armor or can be eaten alive.', 'Swim 98%.', 'Natural camouflage: it buries itself in earth and muck, covers itself in leaves or lies underwater with only eyes, nostrils and mouth showing, so well that a traveler can walk across its nostrils and over its mouth unaware. Digs in soft earth and mud, holds its breath up to 45 minutes, and leaps twice its own length (each leap a melee action). Supernatural Strength and Endurance. Heals 2D6 M.D.C. per 24 hours and grows back a limb or tooth (an eye never returns). Teeth line its throat as well as its mouth, which makes it impossible for other animals to eat and painful to chew. Vulnerable: it fears no animal or man and has no idea what M.D. weapons or armor are; it moves only to attack, to find better hunting ground or to escape, so it cannot dodge and relies on camouflage for defense.', 'Each of these twice per day at will without spending P.P.E., as a third level practitioner of magic: Chameleon and Invisibility: Simple.', 'None.', 'Varies; typically 6-8 feet (1.8 to 2.4 m) across, with a mouth 6 feet (1.8 m) wide that opens 4 feet (1.21 m) deep; most mature adults run 5-16 feet (1.5 to 4.9 m), and the larger are man-eaters', 'Varies with size, from 1500 lbs (675 kg) to 12 tons', 'Unknown; could live for centuries', 'Throughout Dinosaur Swamp, but only in and around swamps, marshes and lakes; most common in Florida, Louisiana and along the Eastern Sandy Marshes, fewer north into the Carolinas', 'None, not even its own kind', 'The Giant Hammer Turtle is its only true enemy; anything that fits in its maw is prey', 'None; animal.', 'A giant, solitary swamp frog that waits hidden and swallows prey whole through a gullet lined with razor teeth, shredding it on the way down; armored or still-solid prey is coughed up and swallowed again, and one in M.D.C. armor it cannot chew is spat out after the third or fourth try. Attacked, it kicks and bites and leaps or swims away. Born dime-sized, it grows as long as it finds food; the largest known, near the Okefenokee, could swallow an adult allosaurus. Most barbarian tribes have lost a member or a hand to one, and children are taught never to reach into holes. Value: none but the legs, eaten only by the desperate (like old, chewy chicken).', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.54-55'),
('saurian-terror', 'Saurian Terror', 'animal', 'rifts', 0, 'Animal predator, considered Miscreant or Diabolic', '{"IQ":"1D4+4","ME":"1D6+4","MA":"1D6","PS":"1D6+20","PP":"1D6+18","PE":"1D6+16","PB":"1D4","Spd":"1D6+8"}', NULL, NULL, '3D6x10+30', '4D6', NULL, 'Mega-Damage by location: Head/Beak 113*; Neck 120*; Wing Arms (2) 115 each*; Hind Legs (2) 100 each*; Wing Membranes (2) 50 each; Stinger Tail 70; Main Body 3D6x10+30. * a Called Shot at -4 to strike. Supernatural P.S. and P.E. I.Q. is low animal intelligence. Spd 1D6+8 is on the ground or climbing; flying it is 2D6+50, minimum 52 (36 mph/57.6 km). On S.D.C. worlds: 2D6x10 S.D.C., 3D6x10 Hit Points, A.R. 10, and its attacks do S.D.C. instead of M.D.', NULL, 15, '{"attacks":3,"initiative":2,"strike":1,"roll":3}', 'Stored are its ground bonuses: +2 on initiative and +1 to strike. Flying it is +3 to strike and +3 to dodge, and +4 on initiative when flying after a successful Prowl. +3 to roll with impact, +4 to save vs disease and poison, +3 vs Horror Factor. All in addition to possible attribute bonuses.', 'Prowl (silent flight and dive attack) 80%; Prowl in a tree, cave and the like 66%; track by smell 50%.', 'A good flier that keeps going three hours without pause or exhaustion; its hearing is good and its nightvision, sharp as a hawk''s, reaches 4000 feet (1219 m). Its body bends and twists like rubber. Poison Stinger: the tail sting does 1D8 S.D.C. (one M.D. point against Mega-Damage prey) and injects a vertigo poison that takes hold within a melee round (15 seconds); the victim must save vs nonlethal poison on 16 or higher for each sting, and a failure cuts his speed by 90%, halves his attacks per melee, reduces all combat bonuses to zero and puts him -60% on skills for 2D4 minutes. It drops a humanoid whose hide is too tough or who fights back with M.D. weapons, and the fall (1D6x100 feet/30.5 to 183 m) does 3D6 S.D.C./Hit Points per 100 feet (30.5 m) to the man inside the armor. Vulnerable: cannot swim, shies from bright light, is blinded 1D4 melee rounds by a sudden flash, and understands neither humanoid opponents nor human technology.', 'None.', 'None.', '8-10 feet (2.4 to 3 m) tall landed on its feet with its head down and 24-32 feet (7.3 to 9.7 m) from beak to tail tip; neck and tail each reach 10-12 feet (3 to 3.6 m), and the wingspan is 32-50 feet (9.7 to 15.2 m)', '800-1100 pounds (360 to 495 kg)', '28-35 years', 'Mainly mountains and forests, but anywhere in Dinosaur Swamp and neighboring Louisiana, Alabama, Mississippi and parts of Tennessee; prefers warm climates, and is rumored in southern Mexico and Central America', 'Only its own kind; it often gathers in flocks of 6D6 that dive like bombers to pick off members of a group, and the bigger the group the better the target', 'Preys on humans, D-Bees, pack dinosaurs, cattle and animals, and is preyed on by Leatherwings and other predators; humans attack it on sight and clear out its roosts near their communities', 'None; animal.', 'A winged horror from an unknown dimension, pterodactyl-like in size and shape but warm-blooded and nearer a giant hairless bat, so its name is a misnomer. Four black eyes, nostrils in its forehead, a beak that opens sideways like shears with blood-sucking pincers inside, a serpentine neck, claws built into its wings and grasping clawed feet, and a prehensile stinger tail. Mostly nocturnal, it roosts in mountains, caves, ruins and trees, eats only live or freshly killed prey, and favors parties, tribes and villages in the wild, even swooping over the streets of Char. It typically stings first, then dives to snatch the dizzy victim away. Value: none; the hide and wings lose their M.D.C. on death and the meat is inedible.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.55-57');
INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'lepidosaur', 'Bite', '1D6+3 S.D.C.', 0, NULL, '+2 to strike and an extra 1D4 S.D.C. while latched.', 0),
('creature', 'lepidosaur', 'Tail Lash', '1D4 S.D.C.', 0, NULL, NULL, 1),
('creature', 'lepidosaur', 'Foot Claw', '1D6+2 S.D.C.', 0, NULL, '30% chance to hook into flesh, or onto a strap or seam of clothing or armor (the Latching Attack).', 2),
('creature', 'lepidosaur', 'Hand Claw', '1D4+1 S.D.C.', 0, NULL, '30% chance to hook into flesh, or onto a strap or seam of clothing or armor (the Latching Attack).', 3),
('creature', 'lepidosaur', 'Swarming Attack', '4D6 S.D.C.', 0, NULL, 'Per melee round, six or more on one victim: -7 to strike, parry and dodge, -25% on skills, and dodging is useless.', 4),
('creature', 'raptor-king', 'Bite', '2D6 M.D.', 1, NULL, '+3 for females. No poison glands.', 0),
('creature', 'raptor-king', 'Punch', '1D6 M.D.', 1, NULL, NULL, 1),
('creature', 'raptor-king', 'Hand Claw', '2D4 M.D.', 1, NULL, NULL, 2),
('creature', 'raptor-king', 'Clawed Feet', '2D6 M.D.', 1, NULL, '+1D6 for females.', 3),
('creature', 'raptor-king', 'Tail Slash', '1D4 M.D.', 1, NULL, 'A blunt strike with the semi-prehensile tail.', 4),
('creature', 'raptor-king', 'Head Butt', '2D4 S.D.C.', 0, NULL, NULL, 5),
('creature', 'razorback-rhinoceros', 'Claw', '4D6 M.D.', 1, NULL, NULL, 0),
('creature', 'razorback-rhinoceros', 'Bite', '3D6 M.D.', 1, NULL, NULL, 1),
('creature', 'razorback-rhinoceros', 'Head Butt', '2D6 M.D.', 1, NULL, 'A warning.', 2),
('creature', 'razorback-rhinoceros', 'Light Horn Jab', '2D6 M.D.', 1, NULL, 'Typically a warning.', 3),
('creature', 'razorback-rhinoceros', 'Horn Stab', '5D6 M.D.', 1, NULL, NULL, 4),
('creature', 'razorback-rhinoceros', 'Gore Horn Strike', '6D6 M.D.', 1, NULL, NULL, 5),
('creature', 'razorback-rhinoceros', 'Power Gore Strike', '1D6x10 M.D.', 1, NULL, 'Printed as 1D6x10 with no unit; counts as one melee attack, once per melee round.', 6),
('creature', 'razorback-rhinoceros', 'Stomp', '2D4 M.D.', 1, NULL, NULL, 7),
('creature', 'razorback-rhinoceros', 'Warning Tail Slash', '2D4 M.D.', 1, NULL, NULL, 8),
('creature', 'razorback-rhinoceros', 'Tail Slash', '5D6 M.D.', 1, NULL, NULL, 9),
('creature', 'razorback-rhinoceros', 'Body Ram', '6D6 M.D.', 1, NULL, '01-60% chance to knock down an opponent up to 15 ft (4.6 m) tall, who loses two melee attacks and initiative.', 10),
('creature', 'razorback-rhinoceros', 'Charging Gore Run', '2D4x10+12 M.D.', 1, NULL, 'Counts as two melee attacks. 01-80% to knock down an opponent up to 22 ft (6.7 m) tall (01-50% if larger), who loses two melee attacks and initiative; humans up to about 10 ft (3 m) are thrown 4D4 yards and may roll with impact. A human in body or power armor saves vs coma/death even if the armor holds; a failure is 5D6 direct to Hit Points and S.D.C., 1D4 broken ribs (speed and combat bonuses halved for 2 weeks) and 1D4x10 minutes unconscious.', 11),
('creature', 'razormouth-frog', 'Mouth Bite', '3D6 M.D.', 1, NULL, '4D6 M.D. or 6D6 M.D. for larger frogs. The first stage of swallowing; each stage is a separate melee attack.', 0),
('creature', 'razormouth-frog', 'Gullet Bite and Swallow', '2D6+12 M.D.', 1, NULL, 'Whatever the frog''s size; the second stage.', 1),
('creature', 'razormouth-frog', 'Stomach Acid', '1D6 M.D.', 1, NULL, 'Per melee round inside its gullet; the third stage. Prey still solid and alive is regurgitated on the next attack and the cycle begins again.', 2),
('creature', 'saurian-terror', 'Talon Strike', '3D6 M.D.', 1, NULL, 'With the lower legs.', 0),
('creature', 'saurian-terror', 'Wing Claws', '2D6 M.D.', 1, NULL, NULL, 1),
('creature', 'saurian-terror', 'Wing Slash', '1D6 M.D.', 1, NULL, NULL, 2),
('creature', 'saurian-terror', 'Bite', '2D6 M.D.', 1, NULL, NULL, 3),
('creature', 'saurian-terror', 'Blood-Sucking Pincers', '1D6 S.D.C.', 0, NULL, 'Or one M.D. point.', 4),
('creature', 'saurian-terror', 'Diving Talon Attack', '6D6+3 M.D.', 1, NULL, 'A power strike that counts as all three melee attacks; a full melee round of flying sets up the next one.', 5),
('creature', 'saurian-terror', 'Poison Stinger', '1D8 S.D.C.', 0, NULL, 'One M.D. point against Mega-Damage prey, plus vertigo poison: save vs nonlethal poison on 16 or higher for each sting.', 6);
INSERT INTO data_script_runs (filename) VALUES ('~254-adventures-in-dinosaur-swamp-creatures-b.sql');
